#[inline(always)]
fn sink_matched(
    &mut self,
    buf: &[u8],
    range: &Range,
) -> Result<bool, S::Error> {
    if self.binary && self.detect_binary(buf, range)? {
        return Ok(false);
    }
    if !self.sink_break_context(range.start())? {
        return Ok(false);
    }
    self.count_lines(buf, range.start());
    let offset = self.absolute_byte_offset + range.start() as u64;
    let linebuf = &buf[*range];
    let keepgoing = self.sink.matched(
        &self.searcher,
        &SinkMatch {
            line_term: self.config.line_term,
            bytes: linebuf,
            absolute_byte_offset: offset,
            line_number: self.line_number,
            buffer: buf,
            bytes_range_in_buffer: range.start()..range.end(),
        },
    )?;
    if !keepgoing {
        return Ok(false);
    }
    self.last_line_visited = range.end();
    self.after_context_left = self.config.after_context;
    self.has_sunk = true;
    Ok(true)
}

fn sink_before_context(
    &mut self,
    buf: &[u8],
    range: &Range,
) -> Result<bool, S::Error> {
    if self.binary && self.detect_binary(buf, range)? {
        return Ok(false);
    }
    self.count_lines(buf, range.start());
    let offset = self.absolute_byte_offset + range.start() as u64;
    let keepgoing = self.sink.context(
        &self.searcher,
        &SinkContext {
            #[cfg(test)]
            line_term: self.config.line_term,
            bytes: &buf[*range],
            kind: SinkContextKind::Before,
            absolute_byte_offset: offset,
            line_number: self.line_number,
        },
    )?;
    if !keepgoing {
        return Ok(false);
    }
    self.last_line_visited = range.end();
    self.has_sunk = true;
    Ok(true)
}

fn sink_after_context(
    &mut self,
    buf: &[u8],
    range: &Range,
) -> Result<bool, S::Error> {
    assert!(self.after_context_left >= 1);

    if self.binary && self.detect_binary(buf, range)? {
        return Ok(false);
    }
    self.count_lines(buf, range.start());
    let offset = self.absolute_byte_offset + range.start() as u64;
    let keepgoing = self.sink.context(
        &self.searcher,
        &SinkContext {
            #[cfg(test)]
            line_term: self.config.line_term,
            bytes: &buf[*range],
            kind: SinkContextKind::After,
            absolute_byte_offset: offset,
            line_number: self.line_number,
        },
    )?;
    if !keepgoing {
        return Ok(false);
    }
    self.last_line_visited = range.end();
    self.after_context_left -= 1;
    self.has_sunk = true;
    Ok(true)
}

